var captchaId="#"+document.getElementById("CaptchaId").value,noInteractionTimeInMinutes;$(function(){$(captchaId).show();$("#captcha-refresh-icon, #"+$("#ModelImageElementId").val()).click(function(){var n={};return n[$("#ModelTokenParameterName").val()]=$("#"+$("#ModelTokenElementId").val()).val(),$.post($("#ModelRefreshUrl").val(),n).always(function(n){eval(n.responseText);$(captchaId).show()}),!1})});noInteractionTimeInMinutes=parseInt(document.getElementById("NoInteractionTimeInMinutes").value);noInteractionTimeInMinutes>0&&setTimeout(function(){window.location.href=window.location.href},noInteractionTimeInMinutes);